{"command":"python3 << 'EOF'
import csv

# Check if any city_name has commas
with open('outputs/t02_eurostat_raw.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if ',' in row['city_name'] or '"' in row['city_name'] or '\n' in row['city_name']:
            print(f"City name needs quoting: {row['city_name']!r}")
            break
    else:
        print("No city names need quoting")
EOF"}
